import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { Component, OnInit } from '@angular/core';
import { NgForm } from '@angular/forms';
import { Router } from '@angular/router';
import { CartItem } from 'src/app/model/CartItem';
import { CartService } from 'src/app/services/cart.service';
import { OrderService } from 'src/app/services/order.service';

@Component({
  selector: 'app-order-details',
  templateUrl: './order-details.component.html',
  styleUrls: ['./order-details.component.scss']
})
export class OrderDetailsComponent implements OnInit {
  cartItems: CartItem[] = [];

  order = {
    address: '',
    contact: '',
    paymentMode: ''
  };

  constructor(
    private cartService: CartService,
    private orderService: OrderService,
    private router: Router,
    private http: HttpClient  // Fixed injection
  ) { }

  ngOnInit(): void {
    this.loadCartItems();
  }

  loadCartItems() {
    this.cartService.getCartItems().subscribe(items => {
      this.cartItems = items; // Ensure items is an array
    });
  }

  placeOrder(form: NgForm) {
    if (form.invalid) {
      console.log('Form is invalid');
      return;
    }

    console.log('Form data to send:', this.order);

    this.http.post('http://localhost:8080/api/orders', this.order)
      .subscribe({
        next: (response: any) => {
          console.log('Order placed successfully', response);
          alert('Order placed successfully!');
          this.router.navigate(['/']); // Optional: navigate after order
        },
        error: (error: HttpErrorResponse) => {
          console.error('Error placing order', error);
          alert('Error placing order: ' + JSON.stringify(error.error));
        }
      });
  }

  getTotalAmount(): number {
    return this.cartItems.reduce((sum, item) => sum + (item.product.price * item.quantity), 0);
  }
}
<div class="order-form-container">
  <h2>Order Details</h2>

  <!-- Cart Items Table -->
  <table class="table table-bordered" *ngIf="cartItems.length > 0">
    <thead>
      <tr>
        <th>Product</th>
        <th>Quantity</th>
        <th>Price (₹)</th>
      </tr>
    </thead>
    <tbody>
      <tr *ngFor="let item of cartItems">
        <td>{{ item.product.title }}</td>
        <td>{{ item.quantity }}</td>
        <td>{{ item.product.price * item.quantity }}</td>
      </tr>
      <tr>
        <td colspan="2"><strong>Total Amount</strong></td>
        <td><strong>{{ getTotalAmount() }}</strong></td>
      </tr>
    </tbody>
  </table>

  <!-- Order Form -->
  <form #orderForm="ngForm" (ngSubmit)="placeOrder(orderForm)">
    <!-- Address -->
     <p>Form valid? {{ orderForm.valid }}</p>
    <div class="form-group">
      <label for="address">Shipping Address</label>
      <textarea id="address" name="address" class="form-control" rows="3"
                required
                [(ngModel)]="order.address"
                #address="ngModel"></textarea>
      <div class="text-danger" *ngIf="address.invalid && address.touched">
        Address is required.
      </div>
    </div>

    <!-- Contact Number -->
    <div class="form-group">
      <label for="contact">Contact Number</label>
      <input type="text" id="contact" name="contact" class="form-control"
             required
             pattern="^[0-9]{10}$"
             [(ngModel)]="order.contact"
             #contact="ngModel">
      <div class="text-danger" *ngIf="contact.invalid && contact.touched">
        Contact number must be 10 digits.
      </div>
    </div>

    <!-- Payment Mode -->
    <div class="form-group">
      <label>Payment Mode</label>
      <div>
        <label>
          <input type="radio" name="paymentMode" value="Cash on Delivery"
                 required
                 [(ngModel)]="order.paymentMode"
                 #paymentMode="ngModel"> Cash on Delivery
        </label>
      </div>
      <div>
        <label>
          <input type="radio" name="paymentMode" value="Credit/Debit Card"
                 [(ngModel)]="order.paymentMode"> Credit/Debit Card
        </label>
      </div>
      <div>
        <label>
          <input type="radio" name="paymentMode" value="UPI"
                 [(ngModel)]="order.paymentMode"> UPI
        </label>
      </div>
      <div class="text-danger" *ngIf="paymentMode.invalid && paymentMode.touched">
        Please select a payment mode.
      </div>
    </div>

    <!-- Place Order Button -->
    <button type="submit" class="btn btn-primary" [disabled]="orderForm.invalid ||  cartItems.length === 0">
      Place Order
    </button>
  </form>
</div>
